<section class="section panel invoicebox"><?php $screenInvoiceLogo=trim((string)($invoice['seller_logo_path']??''));if($screenInvoiceLogo==='')$screenInvoiceLogo=(string)($app['logo_path']??'');if(($app['show_logo_invoice']??'1')==='1'&&$screenInvoiceLogo!==''&&logoAbsolutePath($screenInvoiceLogo)&&is_file((string)logoAbsolutePath($screenInvoiceLogo))):?><div style="margin-bottom:14px"><img src="<?=h(logoUrl($screenInvoiceLogo))?>" alt="<?=h($invoice['seller_name'])?>" style="display:block;max-width:220px;max-height:90px;width:auto;height:auto"></div><?php endif;?><div class="sectionhead"><div><div class="eyebrow">Lasku</div><h1><?=h($invoice['invoice_number'])?></h1><div class="sub"><?=h($invoice['customer_name'])?> · <?=h(trim(($invoice['reg_plate']?:$invoice['nickname']).' · '.$invoice['make'].' '.$invoice['model']))?></div></div><div class="form-actions"><a class="btn" target="_blank" href="?print=invoice&invoice=<?=$invoiceId?>">🖨 Tulosta / PDF</a><a class="btn2" href="?view=invoices">← Laskut</a><a class="btn2" href="?car=<?=(int)$invoice['car_id']?>#historia">Takaisin autoon</a><?php if(invoiceCanDelete($invoice)):?><form method="post" class="delete-invoice-form" data-delete-label="<?=h($invoice['invoice_number'])?>"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="delete_invoice"><input type="hidden" name="invoice_id" value="<?=$invoiceId?>"><button class="danger">Poista laskuluonnos</button></form><?php endif;?></div></div><?php if($invoice['status']==='Luonnos'):?><div class="flash warn">Laskuluonnos on muodostamishetken snapshot huollosta. Huollon myöhemmät muutokset eivät päivitä jo muodostettua laskua automaattisesti. Jos hinnat tai työt muuttuivat, poista luonnos ja muodosta huollosta uusi lasku.</div><?php endif;?>
<div class="grid grid4"><div><label>Päiväys</label><strong><?=h(fiDate($invoice['issue_date']))?></strong></div><div><label>Eräpäivä</label><strong><?=h(fiDate($invoice['due_date']))?></strong></div><div><label>Maksettavaa</label><strong style="font-size:20px"><?=h(money($net+$vat))?></strong></div><div><label>Tila</label><form method="post" class="form-actions" style="margin:0"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="update_invoice_status"><?php editField($db,'invoice',$invoiceId);?><input type="hidden" name="invoice_id" value="<?=$invoiceId?>"><select name="status" onchange="this.form.submit()"><?php foreach(invoiceAllowedStatuses($invoice) as $s):?><option <?=$invoice['status']===$s?'selected':''?>><?=h($s)?></option><?php endforeach;?></select></form></div></div><?php $statusTimes=array_filter([!empty($invoice['sent_at'])?'Lähetetty '.date('d.m.Y H:i',strtotime((string)$invoice['sent_at'])):null,!empty($invoice['paid_at'])?'Maksettu '.date('d.m.Y H:i',strtotime((string)$invoice['paid_at'])):null,!empty($invoice['credited_at'])?'Hyvitetty '.date('d.m.Y H:i',strtotime((string)$invoice['credited_at'])):null]);if($statusTimes):?><div class="tiny" style="margin-top:9px">Tilat: <?=h(implode(' · ',$statusTimes))?></div><?php endif;?>
<div class="invoice-screen-grid"><div class="invoice-screen-card"><div class="eyebrow">Laskuttaja</div><strong><?=h($invoice['seller_name'])?></strong><?php if($invoice['seller_address']):?><div><?=nl2br(h($invoice['seller_address']))?></div><?php endif;?><?php if($invoice['seller_business_id']):?><div>Y-tunnus <?=h($invoice['seller_business_id'])?></div><?php endif;?><?php if($invoice['seller_phone']):?><div><?=h($invoice['seller_phone'])?></div><?php endif;?><?php if($invoice['seller_email']):?><div><?=h($invoice['seller_email'])?></div><?php endif;?></div><div class="invoice-screen-card"><div class="eyebrow">Asiakas</div><strong><?=h($invoice['customer_name']?:'—')?></strong><?php if($invoice['customer_address']):?><div><?=nl2br(h($invoice['customer_address']))?></div><?php endif;?><?php if($invoice['customer_business_id']):?><div>Y-tunnus <?=h($invoice['customer_business_id'])?></div><?php endif;?><?php if($invoice['customer_email']):?><div><?=h($invoice['customer_email'])?></div><?php endif;?></div></div>
<div class="invoice-screen-card"><div class="eyebrow">Ajoneuvo ja työ</div><strong><?=h(trim(($invoice['reg_plate']?:$invoice['nickname']).' · '.$invoice['make'].' '.$invoice['model']))?></strong><div><?=h($invoice['title'])?></div></div>
<div class="tablewrap" style="margin-top:18px"><table><thead><tr><th>Kuvaus</th><th>Määrä</th><th>á ALV 0 %</th><th>ALV</th><th>Veroton</th><th>Verollinen</th></tr></thead><tbody><?php foreach($invoiceLines as $l):$ln=(float)$l['qty']*(float)$l['unit_price_net'];$lg=$ln*(1+(float)$l['vat_rate']/100);?><tr><td><?=h($l['description'])?></td><td><?=h(dec((float)$l['qty'],2).' '.$l['unit'])?></td><td><?=h(money((float)$l['unit_price_net']))?></td><td><?=h(dec((float)$l['vat_rate'],1))?> %</td><td><?=h(money($ln))?></td><td><strong><?=h(money($lg))?></strong></td></tr><?php endforeach;?></tbody></table></div><?php $webVatGroups=[];foreach($invoiceLines as $l){$ln=(float)$l['qty']*(float)$l['unit_price_net'];$vk=number_format((float)$l['vat_rate'],3,'.','');$webVatGroups[$vk]=($webVatGroups[$vk]??0)+$ln*(float)$l['vat_rate']/100;}ksort($webVatGroups,SORT_NUMERIC);?><div class="totals"><div class="totalrow"><span>Veroton yhteensä</span><strong><?=h(money($net))?></strong></div><?php foreach($webVatGroups as $vr=>$vv):?><div class="totalrow"><span>ALV <?=h(dec((float)$vr,1))?> %</span><strong><?=h(money($vv))?></strong></div><?php endforeach;?><div class="totalrow big"><span>Maksettavaa</span><span><?=h(money($net+$vat))?></span></div></div>
<?php if($invoice['seller_iban'] || ((int)($invoice['seller_mobilepay_enabled']??0)===1 && trim((string)($invoice['seller_mobilepay_number']??''))!=='')):?><div class="invoice-payments"><?php if($invoice['seller_iban']):?><div class="invoice-payment-ui"><div class="eyebrow">Tilisiirto</div><strong><?=h($invoice['seller_iban'])?></strong><?php if($invoice['seller_bic']):?><div>BIC <?=h($invoice['seller_bic'])?></div><?php endif;?><?php $invRef=invoiceReference((string)$invoice['invoice_number']);if($invRef!==''):?><div class="invoice-ref">Viitenumero <strong><?=h(invoiceReferenceFormatted($invRef))?></strong></div><div class="tiny">Käytä viitettä maksaessasi. Viestiä ei silloin tarvita.</div><?php else:?><div class="tiny">Viesti: Lasku <?=h($invoice['invoice_number'])?></div><?php endif;?></div><?php endif;?><?php if((int)($invoice['seller_mobilepay_enabled']??0)===1 && trim((string)($invoice['seller_mobilepay_number']??''))!==''):?><div class="invoice-payment-ui"><div class="eyebrow">MobilePay</div><strong><?=h($invoice['seller_mobilepay_number'])?></strong><?php if(trim((string)($invoice['seller_mobilepay_name']??''))!==''):?><div><?=h($invoice['seller_mobilepay_name'])?></div><?php endif;?><div class="tiny">Viestiksi: Lasku <?=h($invoice['invoice_number'])?></div></div><?php endif;?></div><?php endif;?></section>
